import React, { useEffect, useState } from "react";
import io from "socket.io-client";
import {
  fetchDocs,
  createDoc,
  deleteDoc,
  updateDoc,
  addComment,
} from "../api/docs";
import { useAuth } from "../App";

const API_URL =
  process.env.REACT_APP_API_URL ||
  (window.location.hostname.includes("localhost")
    ? "http://localhost:3000"
    : "https://ssr-editor-a4f5aqbafhaedmhp.swedencentral-01.azurewebsites.net");

export default function DocumentList() {
  const { logout } = useAuth();
  const [docs, setDocs] = useState([]);
  const [newTitle, setNewTitle] = useState("");
  const [newContent, setNewContent] = useState("");
  const [newType, setNewType] = useState("text");
  const [socket, setSocket] = useState(null);
  const [comments, setComments] = useState({});
  const [newComments, setNewComments] = useState({});


  useEffect(() => {
    const s = io(API_URL);
    setSocket(s);

    s.on("connect", () => console.log("🟢 Socket ansluten:", s.id));
    s.on("docUpdated", fetchAllDocs);
    s.on("docDeleted", fetchAllDocs);
    s.on("docCreated", fetchAllDocs);
    s.on("commentAdded", ({ docId, comment }) => {
      setComments((prev) => ({
        ...prev,
        [docId]: [...(prev[docId] || []), comment],
      }));
    });

    return () => s.disconnect();
  }, []);


  async function fetchAllDocs() {
    try {
      const data = await fetchDocs();
      setDocs(data);

      for (const d of data) {
        try {
          const res = await fetch(`${API_URL}/documents/${d._id}/comments`, {
            headers: {
              Authorization: "Bearer " + localStorage.getItem("token"),
            },
          });
          if (res.ok) {
            const commentsData = await res.json();
            setComments((prev) => ({ ...prev, [d._id]: commentsData }));
          }
        } catch (err) {
          console.warn("Kommentarer kunde inte hämtas:", err);
        }
      }
    } catch (err) {
      console.error("Fel vid hämtning av dokument:", err);
    }
  }

  useEffect(() => {
    fetchAllDocs();
  }, []);


  async function handleCreate() {
    if (!newTitle.trim() || !newContent.trim())
      return alert("Fyll i titel och innehåll");
    try {
      await createDoc(newTitle, newContent, newType);
      setNewTitle("");
      setNewContent("");
      setNewType("text");
      fetchAllDocs();
      if (socket) socket.emit("docCreated");
    } catch (err) {
      alert("Kunde inte skapa dokument");
      console.error(err);
    }
  }


  async function handleUpdate(id, title, content, type) {
    try {
      await updateDoc(id, title, content, type);
      if (socket) socket.emit("docUpdated", { id });
      fetchAllDocs();
    } catch (err) {
      alert("Fel vid uppdatering");
    }
  }


  async function handleDelete(id) {
    if (!window.confirm("Är du säker på att du vill ta bort dokumentet?")) return;
    try {
      await deleteDoc(id);
      if (socket) socket.emit("docDeleted", { id });
      fetchAllDocs();
    } catch (err) {
      alert("Kunde inte ta bort dokument");
      console.error(err);
    }
  }


  async function handleAddComment(docId) {
    const text = newComments[docId];
    if (!text || !text.trim()) return;
    try {
      const c = await addComment(docId, { text });
      setComments((prev) => ({
        ...prev,
        [docId]: [...(prev[docId] || []), c],
      }));
      setNewComments((prev) => ({ ...prev, [docId]: "" }));
      if (socket) socket.emit("commentAdded", { docId, comment: c });
    } catch (err) {
      console.error("Kunde inte lägga till kommentar:", err);
    }
  }

  return (
    <div style={{ padding: "2rem", maxWidth: 900, margin: "0 auto" }}>
      <h1>📚 Gemensamma dokument</h1>

      <button
        onClick={logout}
        style={{
          marginBottom: "1rem",
          background: "#eee",
          border: "1px solid #ccc",
          borderRadius: 6,
          padding: "0.3rem 1rem",
        }}
      >
        🚪 Logga ut
      </button>

      <h3>➕ Skapa nytt dokument</h3>
      <input
        value={newTitle}
        onChange={(e) => setNewTitle(e.target.value)}
        placeholder="Titel"
        style={{ width: "100%", padding: "0.5rem", marginBottom: "0.5rem" }}
      />
      <textarea
        value={newContent}
        onChange={(e) => setNewContent(e.target.value)}
        placeholder="Innehåll"
        rows="3"
        style={{ width: "100%", padding: "0.5rem", marginBottom: "0.5rem" }}
      />
      <select
        value={newType}
        onChange={(e) => setNewType(e.target.value)}
        style={{ marginBottom: "0.5rem" }}
      >
        <option value="text">📝 Text</option>
        <option value="code">💻 Kod</option>
      </select>
      <br />
      <button onClick={handleCreate}>Skapa</button>

      <hr style={{ margin: "2rem 0" }} />

      {docs.length === 0 ? (
        <p>Inga dokument ännu.</p>
      ) : (
        docs.map((doc) => (
          <div
            key={doc._id}
            style={{
              background: "#fff",
              border: "1px solid #ccc",
              borderRadius: 8,
              padding: "1rem",
              marginBottom: "1rem",
            }}
          >
            <input
              value={doc.title}
              onChange={(e) =>
                setDocs((prev) =>
                  prev.map((d) =>
                    d._id === doc._id ? { ...d, title: e.target.value } : d
                  )
                )
              }
              style={{
                width: "100%",
                fontSize: "1.1rem",
                marginBottom: "0.5rem",
              }}
            />
            <textarea
              value={doc.content}
              onChange={(e) =>
                setDocs((prev) =>
                  prev.map((d) =>
                    d._id === doc._id ? { ...d, content: e.target.value } : d
                  )
                )
              }
              rows="4"
              style={{
                width: "100%",
                marginBottom: "0.5rem",
                padding: "0.5rem",
              }}
            />
            <div>
              <button
                onClick={() =>
                  handleUpdate(doc._id, doc.title, doc.content, doc.type)
                }
              >
                💾 Spara
              </button>
              <button
                onClick={() => handleDelete(doc._id)}
                style={{ marginLeft: "0.5rem" }}
              >
                🗑️ Ta bort
              </button>
            </div>

            {/* === Kommentarer === */}
            <div style={{ marginTop: "1rem" }}>
              <h4>💬 Kommentarer</h4>
              {comments[doc._id]?.length > 0 ? (
                comments[doc._id].map((c, i) => (
                  <div
                    key={i}
                    style={{
                      background: "#f9f9f9",
                      border: "1px solid #ddd",
                      borderRadius: 5,
                      padding: "0.4rem",
                      marginBottom: "0.3rem",
                    }}
                  >
                    <b>{c.user || c.userEmail || c.user_email || c.user?.email || c.email || "Okänd"}:</b> {c.text}

                  </div>
                ))
              ) : (
                <p>Inga kommentarer.</p>
              )}
              <textarea
                placeholder="Skriv en kommentar..."
                value={newComments[doc._id] || ""}
                onChange={(e) =>
                  setNewComments((prev) => ({
                    ...prev,
                    [doc._id]: e.target.value,
                  }))
                }
                rows="2"
                style={{
                  width: "100%",
                  padding: "0.4rem",
                  marginTop: "0.3rem",
                }}
              />
              <button
                onClick={() => handleAddComment(doc._id)}
                style={{ marginTop: "0.3rem" }}
              >
                ➕ Lägg till kommentar
              </button>
            </div>
          </div>
        ))
      )}
    </div>
  );
}
