import React, { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import { useAuth } from "../App";
import { fetchDoc, updateDoc, deleteDoc, addComment } from "../api/docs";
import { execCode } from "../api/docs";
import { io } from "socket.io-client";
import CodeMirror from "@uiw/react-codemirror";
import { javascript } from "@codemirror/lang-javascript";

const API_URL =
  process.env.REACT_APP_API_URL ||
  (window.location.hostname.includes("localhost")
    ? "http://localhost:3000"
    : "https://ssr-editor-a4f5aqbafhaedmhp.swedencentral-01.azurewebsites.net");

export default function DocumentEditor() {
  const { id } = useParams();
  const { user } = useAuth();
  const [doc, setDoc] = useState(null);
  const [comments, setComments] = useState([]);
  const [newComment, setNewComment] = useState("");
  const [output, setOutput] = useState("");
  const [socket, setSocket] = useState(null);

  // === Hämta dokument ===
  useEffect(() => {
    async function load() {
      const data = await fetchDoc(id);
      setDoc(data);
      // Hämta kommentarer
      const res = await fetch(`${API_URL}/documents/${id}/comments`, {
        headers: { Authorization: "Bearer " + localStorage.getItem("token") },
      });
      const comm = await res.json();
      setComments(comm);
    }
    load();

    const s = io(API_URL);
    setSocket(s);
    s.emit("joinDoc", id);

    s.on("docUpdated", (updated) => {
      if (updated._id === id) setDoc(updated);
    });

    s.on("newComment", (c) => {
      if (c.documentId === id) setComments((prev) => [...prev, c]);
    });

    return () => s.disconnect();
  }, [id]);


  async function handleSave() {
    const updated = await updateDoc(id, doc.title, doc.content, doc.type);
    setDoc(updated);
    socket.emit("docUpdated", updated);
  }

  
  async function handleDelete() {
    if (!window.confirm("Vill du verkligen ta bort dokumentet?")) return;
    await deleteDoc(id);
    window.location.href = "/";
  }


  async function handleAddComment() {
    if (!newComment.trim()) return;
    const c = await addComment(id, { text: newComment });
    setComments((prev) => [...prev, c]);
    socket.emit("newComment", c);
    setNewComment("");
  }

  
  function toggleType() {
    const newType = doc.type === "code" ? "text" : "code";
    const updated = { ...doc, type: newType };
    setDoc(updated);
  }

  
  async function handleRunCode() {
    if (!doc || doc.type !== "code") return;
    try {
      const res = await fetch(`${API_URL}/documents/${id}/exec`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: "Bearer " + localStorage.getItem("token"),
        },
        body: JSON.stringify({ code: doc.content }),
      });
      const data = await res.json();
      setOutput(data.output || data.error || "Inget resultat");
    } catch (err) {
      setOutput("Fel vid körning av kod");
    }
  }

  if (!doc) return <p>Laddar dokument...</p>;

  return (
    <div style={{ padding: "1rem" }}>
      <h2>{doc.title}</h2>
      <button onClick={toggleType}>
        Växla till {doc.type === "code" ? "text-läge" : "code-läge"}
      </button>

      {doc.type === "code" ? (
  <>
    <CodeMirror
      value={doc.content}
      height="200px"
      extensions={[javascript()]}
      onChange={(value) => setDoc({ ...doc, content: value })}
    />

    <div style={{ marginTop: "0.5rem" }}>
      <button onClick={handleSave}>💾 Spara</button>

      {/* Kör kod-knapp visas endast i code-läge */}
      {doc.type === "code" && (
        <button onClick={handleRunCode}>▶ Kör kod</button>
      )}

      <button onClick={handleDelete}>🗑️ Ta bort</button>
    </div>

    {output && (
      <pre
        style={{
          background: "#111",
          color: "#0f0",
          padding: "0.5rem",
          borderRadius: "4px",
          marginTop: "0.5rem",
        }}
      >
        {output}
      </pre>
    )}
  </>
) : (


        <>
          <textarea
            value={doc.content}
            onChange={(e) => setDoc({ ...doc, content: e.target.value })}
            rows={8}
            style={{ width: "100%", marginTop: "0.5rem" }}
          />
          <div style={{ marginTop: "0.5rem" }}>
            <button onClick={handleSave}>💾 Spara</button>
            <button onClick={handleDelete}>🗑️ Ta bort</button>
          </div>
        </>
      )}

      <hr />
      <h3>💬 Kommentarer</h3>
      {comments.length === 0 ? (
        <p>Inga kommentarer än.</p>
      ) : (
        comments.map((c, i) => (
          <p key={i}>
            <strong>{c.user}:</strong> {c.text}
          </p>
        ))
      )}
      <textarea
        value={newComment}
        onChange={(e) => setNewComment(e.target.value)}
        placeholder="Ny kommentar..."
        rows={2}
        style={{ width: "100%" }}
      />
      <button onClick={handleAddComment}>💬 Kommentera</button>
    </div>
  );
}
