import React, { useState, useEffect } from "react";
import { registerUser } from "../api/auth";
import { useNavigate, useSearchParams, Link } from "react-router-dom";

export default function Register() {
  const nav = useNavigate();
  const [params] = useSearchParams();
  const token = params.get("token");

  const [email, setEmail] = useState("");
  const [name, setName]   = useState("");
  const [password, setPassword] = useState("");

  async function submit(e) {
    e.preventDefault();
    try {
      await registerUser({ email, password, name });
      alert("Registrerad! Logga in sedan.");
      if (token) nav(`/login?token=${token}`);
      else nav("/login");
    } catch {
      alert("Registrering misslyckades.");
    }
  }

  return (
    <div style={{ padding: 20, maxWidth: 400, margin: "0 auto" }}>
      <h2>Registrera</h2>
      <form onSubmit={submit}>
        <input placeholder="Namn" value={name} onChange={(e)=>setName(e.target.value)} />
        <input placeholder="E-post" value={email} onChange={(e)=>setEmail(e.target.value)} />
        <input type="password" placeholder="Lösenord" value={password} onChange={(e)=>setPassword(e.target.value)} />
        <button type="submit">Skapa konto</button>
      </form>
      <p>Har konto? <Link to="/login">Logga in</Link></p>
    </div>
  );
}
