import axios from "axios";

const API_URL =
  process.env.REACT_APP_API_URL ||
  (window.location.hostname.includes("localhost")
    ? "http://localhost:3000"
    : "https://ssr-editor-a4f5aqbafhaedmhp.swedencentral-01.azurewebsites.net");

function authHeaders() {
  const token = localStorage.getItem("token");
  return token ? { Authorization: `Bearer ${token}` } : {};
}

export const testCors = async () => {
  try {
    const res = await fetch(`${API_URL}/health`, {
      method: "GET",
      mode: "cors",
    });
    console.log("Health:", await res.json());
  } catch (err) {
    console.error("CORS/health fail:", err);
  }
};

export async function apiRegister({ email, password, name }) {
  const res = await axios.post(`${API_URL}/auth/register`, {
    email,
    password,
    name,
  });
  return res.data;
}

export async function apiLogin({ email, password }) {
  const res = await axios.post(`${API_URL}/auth/login`, { email, password });
  return res.data;
}

export async function apiMe() {
  const res = await axios.get(`${API_URL}/auth/me`, { headers: authHeaders() });
  return res.data.user;
}

export const fetchDocs = async () => {
  const res = await axios.get(`${API_URL}/documents`, {
    headers: authHeaders(),
  });
  return res.data;
};

export const fetchDoc = async (id) => {
  const res = await axios.get(`${API_URL}/documents/${id}`, {
    headers: authHeaders(),
  });
  return res.data;
};

export const createDoc = async (title, content, type = "text") => {
  const res = await axios.post(
    `${API_URL}/documents`,
    { title, content, type },
    { headers: { "Content-Type": "application/json", ...authHeaders() } }
  );
  return res.data;
};

export const updateDoc = async (id, title, content, type) => {
  const payload = {};
  if (title !== undefined) payload.title = title;
  if (content !== undefined) payload.content = content;
  if (type !== undefined) payload.type = type;
  const res = await axios.put(`${API_URL}/documents/${id}`, payload, {
    headers: authHeaders(),
  });
  return res.data;
};

export const deleteDoc = async (id) => {
  const res = await axios.delete(`${API_URL}/documents/${id}`, {
    headers: authHeaders(),
  });
  return res.data;
};

export const shareDoc = async (id, email) => {
  const res = await axios.post(
    `${API_URL}/documents/${id}/share`,
    { email },
    { headers: authHeaders() }
  );
  return res.data;
};

export const acceptInvite = async (token) => {
  const res = await axios.post(
    `${API_URL}/invites/accept`,
    { token },
    { headers: authHeaders() }
  );
  return res.data;
};

export const addComment = async (id, { line, text }) => {
  const res = await axios.post(
    `${API_URL}/documents/${id}/comments`,
    { line, text },
    { headers: authHeaders() }
  );
  return res.data;
};

export const execCode = async (id, code) => {
  const res = await axios.post(
    `${API_URL}/documents/${id}/exec`,
    { code },
    { headers: authHeaders() }
  );
  return res.data;
};
